import sys

mapping = {
    "zero": 0, "one": 1, "two": 2, "three": 3, "four": 4,
    "five": 5, "six": 6, "seven": 7, "eight": 8, "nine": 9
}

data = sys.stdin.read().strip()
if not data:
    print()
else:
    words = data.split()
    sorted_words = sorted(words, key=lambda w: mapping[w])
    print(' '.join(sorted_words))

import sys

s = sys.stdin.read()
if any(ch.isalpha() for ch in s):
    sys.stdout.write(s.swapcase())
else:
    sys.stdout.write(s[::-1])

import sys

s = sys.stdin.read()
has_letter = any(ch.isalpha() for ch in s)

if has_letter:
    out = []
    for ch in s:
        if ch.isalpha():
            out.append(ch.swapcase())
        else:
            out.append(ch)
    result = ''.join(out)
else:
    result = s[::-1]

sys.stdout.write(result)

