class ReturnsExtension:
    def __init__(self, data):
        self.data = data

    def count_upper_minus_lower(self, s):
        upper = sum(1 for c in s if c.isupper())
        lower = sum(1 for c in s if c.islower())
        return upper - lower

    def best_extension(self):
        # data is expected to be a dict: {extension: string_content}
        best_ext = None
        best_score = None
        for ext, content in self.data.items():
            score = self.count_upper_minus_lower(content)
            if best_score is None or score > best_score:
                best_score = score
                best_ext = ext
        return best_ext, best_score if best_score is not None else None

# Example usage:
if __name__ == "__main__":
    # Mock data: mapping of extensions to their content
    data = {
        ".extA": "AbCdEf",
        ".extB": "abcdef",
        ".extC": "AABBccDD"
    }

    re = ReturnsExtension(data)
    best_ext, score = re.best_extension()
    print(f"{best_ext} {score}")
